{
  "name": "School Pickup Coordinator",
  "description": "A real-time school pickup coordination app connecting parents and teachers. Parents can notify arrival via mobile number search, and teachers get instant updates on a dashboard."
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    host: true,
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Student {
  id: number;
  student_name: string;
  class_name: string;
  parent_mobile: string;
  status: boolean;
  last_called_at: string | null;
}

export interface RPCParams {
  search_number: string;
}

import { createClient } from '@supabase/supabase-js';

// Hardcoded credentials as requested by the user
const SUPABASE_URL = 'https://nytydgmbtshgslkedjwe.supabase.co';
const SUPABASE_KEY = 'sb_publishable_uqZqdXCP57USsTzP93uF1A_y9q3yEbx';

export const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

import React, { useState } from 'react';
import { supabase } from '../services/supabase';
import { Student } from '../types';
import { Phone, Search, Loader2, CheckCircle2 } from 'lucide-react';

export const ParentView: React.FC = () => {
  const [mobileInput, setMobileInput] = useState('');
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!mobileInput.trim()) return;

    setLoading(true);
    setError('');
    setStudents([]);

    try {
      const { data, error } = await supabase.rpc('match_parent_mobile', {
        search_number: mobileInput.trim(),
      });

      if (error) throw error;

      if (data) {
        setStudents(data as Student[]);
        if (data.length === 0) {
          setError('No students found linked to this number.');
        }
      }
    } catch (err: any) {
      console.error('Error searching students:', err);
      setError('Failed to search. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleCallStudent = async (student: Student) => {
    try {
      const now = new Date().toISOString();
      const { error } = await supabase
        .from('students')
        .update({ status: true, last_called_at: now })
        .eq('id', student.id);

      if (error) throw error;

      // Optimistic update
      setStudents((prev) =>
        prev.map((s) =>
          s.id === student.id ? { ...s, status: true, last_called_at: now } : s
        )
      );
    } catch (err) {
      console.error('Error calling student:', err);
      alert('Failed to update status.');
    }
  };

  // Helper to check if a call is recent (within 3 hours)
  const isCallRecent = (lastCalledAt: string | null) => {
    if (!lastCalledAt) return false;
    const diff = new Date().getTime() - new Date(lastCalledAt).getTime();
    return diff < 3 * 60 * 60 * 1000; // 3 hours
  };

  return (
    <div className="max-w-md mx-auto p-6 bg-white shadow-xl rounded-2xl mt-10 border border-gray-100">
      <div className="text-center mb-8">
        <h1 className="text-2xl font-bold text-gray-800 mb-2">Pickup Check-in</h1>
        <p className="text-gray-500">Enter your mobile number to notify the teacher.</p>
      </div>

      <form onSubmit={handleSearch} className="mb-8">
        <div className="relative">
          <input
            type="tel"
            className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-lg"
            placeholder="e.g. 057..."
            value={mobileInput}
            onChange={(e) => setMobileInput(e.target.value)}
          />
          <Phone className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
        </div>
        <button
          type="submit"
          disabled={loading || !mobileInput}
          className="w-full mt-4 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-xl transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Search className="w-5 h-5" />}
          Find Students
        </button>
      </form>

      {error && (
        <div className="bg-red-50 text-red-600 p-4 rounded-xl mb-6 text-center text-sm">
          {error}
        </div>
      )}

      <div className="space-y-4">
        {students.map((student) => {
          const calledRecently = student.status && isCallRecent(student.last_called_at);

          return (
            <div
              key={student.id}
              className={`p-5 rounded-xl border-2 transition-all ${
                calledRecently
                  ? 'border-green-500 bg-green-50'
                  : 'border-gray-100 bg-white hover:border-blue-200'
              }`}
            >
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="text-lg font-bold text-gray-900">{student.student_name}</h3>
                  <p className="text-sm text-gray-500 font-medium">{student.class_name}</p>
                </div>
                {calledRecently && (
                  <span className="flex items-center gap-1 text-green-600 text-xs font-bold uppercase tracking-wider bg-green-100 px-2 py-1 rounded-full">
                    <CheckCircle2 className="w-3 h-3" /> Called
                  </span>
                )}
              </div>

              <button
                onClick={() => handleCallStudent(student)}
                disabled={calledRecently}
                className={`w-full py-2.5 px-4 rounded-lg font-semibold text-sm transition-all ${
                  calledRecently
                    ? 'bg-green-200 text-green-800 cursor-default'
                    : 'bg-gray-900 text-white hover:bg-gray-800 shadow-md hover:shadow-lg transform active:scale-95'
                }`}
              >
                {calledRecently ? 'Teacher Notified' : 'Call Student'}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabase';
import { Student } from '../types';
import { LogOut, RefreshCw, Users } from 'lucide-react';

interface TeacherViewProps {
  onLogout: () => void;
}

export const TeacherView: React.FC<TeacherViewProps> = ({ onLogout }) => {
  const [students, setStudents] = useState<Student[]>([]);
  const [activeTab, setActiveTab] = useState<string>('');
  const [loading, setLoading] = useState(true);

  // Helper: 3-hour rule
  const isActive = (student: Student) => {
    if (!student.status || !student.last_called_at) return false;
    const diff = new Date().getTime() - new Date(student.last_called_at).getTime();
    return diff < 3 * 60 * 60 * 1000;
  };

  const fetchStudents = async () => {
    const { data, error } = await supabase
      .from('students')
      .select('*')
      .order('class_name', { ascending: true })
      .order('student_name', { ascending: true });

    if (!error && data) {
      setStudents(data as Student[]);
      // Set initial tab if not set
      if (!activeTab && data.length > 0) {
        setActiveTab((data[0] as Student).class_name);
      }
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchStudents();

    // Realtime subscription
    const channel = supabase
      .channel('public:students')
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'students' },
        (payload) => {
          const updatedStudent = payload.new as Student;
          setStudents((prev) =>
            prev.map((s) => (s.id === updatedStudent.id ? updatedStudent : s))
          );
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Group students by class
  const classes = Array.from(new Set(students.map((s) => s.class_name))).sort();
  const filteredStudents = students.filter((s) => s.class_name === activeTab);

  return (
    <div className="flex flex-col h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-gray-200 px-6 py-4 flex justify-between items-center z-10 sticky top-0">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-blue-100 rounded-lg">
            <Users className="w-6 h-6 text-blue-600" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-gray-900">Teacher Dashboard</h1>
            <p className="text-xs text-gray-500">Real-time pickup monitor</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
             onClick={fetchStudents}
             className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-500"
             title="Refresh Data"
          >
            <RefreshCw className="w-5 h-5" />
          </button>
          <button
            onClick={onLogout}
            className="flex items-center gap-2 text-sm font-medium text-red-600 hover:text-red-700 bg-red-50 hover:bg-red-100 px-4 py-2 rounded-lg transition-colors"
          >
            <LogOut className="w-4 h-4" />
            Logout
          </button>
        </div>
      </header>

      {/* Class Tabs */}
      <div className="bg-white border-b border-gray-200 px-6 py-2 flex gap-2 overflow-x-auto no-scrollbar">
        {classes.map((cls) => (
          <button
            key={cls}
            onClick={() => setActiveTab(cls)}
            className={`px-4 py-2 rounded-full text-sm font-semibold whitespace-nowrap transition-all ${
              activeTab === cls
                ? 'bg-blue-600 text-white shadow-md'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            Class {cls}
          </button>
        ))}
      </div>

      {/* Content */}
      <main className="flex-1 overflow-y-auto p-6">
        {loading ? (
          <div className="flex justify-center items-center h-full">
            <RefreshCw className="w-8 h-8 text-blue-500 animate-spin" />
          </div>
        ) : filteredStudents.length === 0 ? (
          <div className="text-center text-gray-500 mt-20">
            No students found in this class.
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {filteredStudents.map((student) => {
              const active = isActive(student);
              return (
                <div
                  key={student.id}
                  className={`relative p-5 rounded-xl border-2 shadow-sm transition-all duration-300 ${
                    active
                      ? 'bg-green-500 border-green-600 text-white transform scale-105 shadow-lg'
                      : 'bg-white border-gray-100 text-gray-800'
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <h3 className={`text-lg font-bold ${active ? 'text-white' : 'text-gray-900'}`}>
                      {student.student_name}
                    </h3>
                  </div>

                  <div className={`mt-2 text-sm font-medium ${active ? 'text-green-100' : 'text-gray-500'}`}>
                    ID: #{student.id}
                  </div>

                  {active && (
                    <div className="absolute top-3 right-3">
                      <span className="animate-pulse w-3 h-3 bg-white rounded-full block"></span>
                    </div>
                  )}

                  <div className={`mt-4 text-xs font-medium uppercase tracking-wider ${active ? 'text-green-100' : 'text-gray-400'}`}>
                    {active ? 'Parent Arrived' : 'Waiting'}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </main>
    </div>
  );
};

