import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabase';
import { Student } from '../types';
import { LogOut, RefreshCw, AlertCircle, Volume2, School } from 'lucide-react';

interface TeacherViewProps {
  onLogout: () => void;
}

export const TeacherView: React.FC<TeacherViewProps> = ({ onLogout }) => {
  const [students, setStudents] = useState<Student[]>([]);
  const [activeTab, setActiveTab] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');

  const isActive = (student: Student) => {
    if (!student.last_called_at) return false;
    const diff = new Date().getTime() - new Date(student.last_called_at).getTime();
    return diff < 3 * 60 * 60 * 1000;
  };

  const fetchStudents = async () => {
    setLoading(true);
    setErrorMsg('');

    const { data, error } = await supabase
      .from('students')
      .select('*')
      .order('class_name', { ascending: true })
      .order('student_name', { ascending: true });

    if (error) {
      console.error('Error fetching students:', error);
      setErrorMsg(error.message);
    } else if (data) {
      setStudents(data as Student[]);
      if (!activeTab && data.length > 0) {
        setActiveTab((data[0] as Student).class_name);
      }
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchStudents();

    const channel = supabase
      .channel('public:students')
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'students' },
        (payload) => {
          const updatedStudent = payload.new as Student;
          setStudents((prev) =>
            prev.map((s) => (s.id === updatedStudent.id ? updatedStudent : s))
          );
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const classes = Array.from(new Set(students.map((s) => s.class_name))).sort();
  const filteredStudents = students.filter((s) => s.class_name === activeTab);

  return (
    <div className="flex flex-col h-screen bg-gray-50/50 relative overflow-hidden">
      {/* Subtle Background Elements */}
      <div className="absolute top-0 right-0 w-96 h-96 bg-blue-500/5 rounded-full blur-[100px] pointer-events-none" />
      <div className="absolute bottom-0 left-0 w-96 h-96 bg-purple-500/5 rounded-full blur-[100px] pointer-events-none" />

      {/* Dashboard Header */}
      <header className="glass-panel sticky top-0 z-30 px-6 py-4 shadow-sm border-b border-white/50">
        <div className="flex justify-between items-center max-w-7xl mx-auto">
          <div className="flex items-center gap-4">
            <img src="https://i.ibb.co/bgFrgXkW/meis.png" className="h-12 w-auto drop-shadow-sm" alt="Logo" />
            <div className="hidden sm:block">
              <h1 className="text-lg font-bold text-gray-900 leading-tight">Teacher Dashboard</h1>
              <p className="text-xs text-gray-500 font-medium">Real-time Monitor</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
               onClick={fetchStudents}
               className="p-2.5 bg-white/50 hover:bg-white text-gray-600 hover:text-blue-600 rounded-xl transition-all border border-transparent hover:border-blue-100 shadow-sm"
               title="Refresh Data"
            >
              <RefreshCw className="w-5 h-5" />
            </button>
            <button
              onClick={onLogout}
              className="flex items-center gap-2 text-sm font-semibold text-white bg-red-500 hover:bg-red-600 px-5 py-2.5 rounded-xl shadow-lg shadow-red-500/20 transition-all hover:scale-105"
            >
              <LogOut className="w-4 h-4" />
              <span className="hidden sm:inline">Logout</span>
            </button>
          </div>
        </div>

        {/* Horizontal Scrollable Tabs */}
        <div className="mt-6 flex gap-2 overflow-x-auto pb-2 no-scrollbar max-w-7xl mx-auto">
          {classes.map((cls) => (
            <button
              key={cls}
              onClick={() => setActiveTab(cls)}
              className={`px-5 py-2.5 rounded-xl text-sm font-bold whitespace-nowrap transition-all duration-300 ${
                activeTab === cls
                  ? 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg shadow-blue-500/30 scale-105'
                  : 'bg-white/60 text-gray-600 hover:bg-white hover:text-blue-600 border border-transparent hover:border-blue-100'
              }`}
            >
              Class {cls}
            </button>
          ))}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto p-6 scroll-smooth">
        <div className="max-w-7xl mx-auto">
          {loading ? (
            <div className="flex flex-col justify-center items-center h-64 gap-4">
              <div className="relative">
                 <div className="w-12 h-12 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
              </div>
              <p className="text-gray-500 font-medium">Loading class data...</p>
            </div>
          ) : errorMsg ? (
            <div className="flex flex-col justify-center items-center h-64 text-red-500 gap-3">
              <div className="p-3 bg-red-100 rounded-full">
                <AlertCircle className="w-8 h-8" />
              </div>
              <p className="font-medium text-lg">System Error</p>
              <p className="text-sm text-gray-600 bg-white px-4 py-2 rounded-lg border border-red-100">{errorMsg}</p>
            </div>
          ) : filteredStudents.length === 0 ? (
            <div className="flex flex-col justify-center items-center h-64 text-gray-400 gap-4">
              <div className="p-6 bg-white/50 rounded-full border border-dashed border-gray-300">
                <School className="w-12 h-12 opacity-50" />
              </div>
              <p className="text-lg font-medium">No students found in Class {activeTab}.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 pb-20">
              {filteredStudents.map((student) => {
                const active = isActive(student);
                return (
                  <div
                    key={student.id}
                    className={`relative p-6 rounded-3xl border transition-all duration-500 group ${
                      active
                        ? 'bg-gradient-to-br from-green-500 to-emerald-600 border-transparent text-white shadow-xl shadow-green-500/30 transform scale-[1.02] z-10'
                        : 'bg-white/70 border-white/50 text-gray-800 hover:bg-white hover:shadow-xl hover:shadow-blue-900/5 hover:-translate-y-1 backdrop-blur-sm'
                    }`}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className={`text-xl font-bold leading-tight ${active ? 'text-white' : 'text-gray-800'}`}>
                          {student.student_name}
                        </h3>
                        <p className={`mt-1 text-xs font-semibold uppercase tracking-wider ${active ? 'text-green-100' : 'text-gray-400'}`}>
                          #{student.id}
                        </p>
                      </div>
                      {active && (
                         <div className="p-2 bg-white/20 rounded-lg backdrop-blur-md animate-pulse">
                           <Volume2 className="w-5 h-5 text-white" />
                         </div>
                      )}
                    </div>

                    <div className="mt-6 flex items-center justify-between">
                      <div className={`px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${
                        active 
                          ? 'bg-white/20 text-white backdrop-blur-sm' 
                          : 'bg-gray-100 text-gray-500'
                      }`}>
                        {active ? 'Waiting Now' : 'In Class'}
                      </div>

                      {active && (
                        <span className="flex h-3 w-3">
                          <span className="animate-ping absolute inline-flex h-3 w-3 rounded-full bg-white opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-3 w-3 bg-white"></span>
                        </span>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

