import React, { useState } from 'react';
import { supabase } from '../services/supabase';
import { Student } from '../types';
import { Phone, Search, Loader2, CheckCircle2, User, Sparkles } from 'lucide-react';

export const ParentView: React.FC = () => {
  const [mobileInput, setMobileInput] = useState('');
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!mobileInput.trim()) return;

    setLoading(true);
    setError('');
    setStudents([]);

    try {
      const { data, error } = await supabase.rpc('match_parent_mobile', {
        search_number: mobileInput.trim(),
      });

      if (error) throw error;

      if (data) {
        setStudents(data as Student[]);
        if (data.length === 0) {
          setError('No students found linked to this number.');
        }
      }
    } catch (err: any) {
      console.error('Error searching students:', err);
      setError(err.message || 'Failed to search. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleCallStudent = async (student: Student) => {
    try {
      const now = new Date().toISOString();
      const { error } = await supabase
        .from('students')
        .update({ last_called_at: now })
        .eq('id', student.id);

      if (error) throw error;

      setStudents((prev) =>
        prev.map((s) =>
          s.id === student.id ? { ...s, last_called_at: now } : s
        )
      );
    } catch (err: any) {
      console.error('Error calling student:', err);
      alert(`Failed to update status: ${err.message}`);
    }
  };

  const isCallRecent = (lastCalledAt: string | null) => {
    if (!lastCalledAt) return false;
    const diff = new Date().getTime() - new Date(lastCalledAt).getTime();
    return diff < 3 * 60 * 60 * 1000;
  };

  return (
    <div className="flex flex-col items-center">
      {/* Search Card */}
      <div className="glass-panel w-full max-w-lg rounded-3xl p-8 shadow-2xl shadow-blue-900/10 mb-8 border border-white/60">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-gradient-to-tr from-blue-500 to-cyan-400 text-white mb-4 shadow-lg shadow-blue-500/30">
            <Sparkles className="w-6 h-6" />
          </div>
          <h1 className="text-2xl font-bold text-gray-800 mb-2">Pickup Check-in</h1>
          <p className="text-gray-500">Enter your mobile number to notify the teacher.</p>
        </div>

        <form onSubmit={handleSearch} className="space-y-6">
          <div className="relative group">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
              <Phone className="h-5 w-5 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
            </div>
            <input
              type="number"
              className="block w-full pl-12 pr-4 py-4 bg-white/50 border border-gray-200 rounded-2xl text-lg placeholder-gray-400 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:bg-white transition-all duration-300 outline-none backdrop-blur-sm [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
              placeholder=""
              value={mobileInput}
              onChange={(e) => setMobileInput(e.target.value)}
            />
          </div>
          <button
            type="submit"
            disabled={loading || !mobileInput}
            className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-semibold py-4 px-6 rounded-2xl shadow-lg shadow-blue-600/20 transform transition-all duration-300 hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Search className="w-5 h-5" />}
            Find Students
          </button>
        </form>

        {error && (
          <div className="mt-6 p-4 bg-red-50/80 backdrop-blur-sm text-red-600 rounded-xl text-center text-sm font-medium border border-red-100 animate-in fade-in slide-in-from-top-2">
            {error}
          </div>
        )}
      </div>

      {/* Results Grid */}
      <div className="w-full grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {students.map((student, idx) => {
          const calledRecently = isCallRecent(student.last_called_at);

          return (
            <div
              key={student.id}
              className={`relative overflow-hidden group p-6 rounded-3xl border transition-all duration-500 animate-in fade-in slide-in-from-bottom-4 ${
                calledRecently
                  ? 'bg-gradient-to-br from-green-50 to-emerald-100/50 border-green-200 shadow-xl shadow-green-900/5'
                  : 'glass-card hover:bg-white hover:shadow-xl hover:shadow-blue-900/10 hover:border-blue-200 border-white/60'
              }`}
              style={{ animationDelay: `${idx * 100}ms` }}
            >
              {/* Status Indicator */}
              <div className="flex justify-between items-start mb-6">
                <div className={`p-3 rounded-2xl ${calledRecently ? 'bg-green-100 text-green-600' : 'bg-blue-50 text-blue-600'}`}>
                   <User className="w-6 h-6" />
                </div>
                {calledRecently && (
                  <span className="flex items-center gap-1.5 text-green-700 text-xs font-bold uppercase tracking-wider bg-green-100/80 px-3 py-1.5 rounded-full shadow-sm">
                    <CheckCircle2 className="w-3.5 h-3.5" /> Called
                  </span>
                )}
              </div>

              <div className="mb-6">
                <h3 className="text-xl font-bold text-gray-800 mb-1">{student.student_name}</h3>
                <p className="text-sm text-gray-500 font-medium bg-gray-100/50 inline-block px-3 py-1 rounded-lg">
                  {student.class_name}
                </p>
              </div>

              <button
                onClick={() => handleCallStudent(student)}
                disabled={calledRecently}
                className={`w-full py-3.5 px-4 rounded-xl font-semibold text-sm transition-all duration-300 flex items-center justify-center gap-2 ${
                  calledRecently
                    ? 'bg-green-200/50 text-green-800 cursor-default'
                    : 'bg-gray-900 text-white hover:bg-blue-600 shadow-md hover:shadow-lg hover:shadow-blue-600/30 transform active:scale-95'
                }`}
              >
                {calledRecently ? 'Teacher Notified' : 'Call Student'}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
};

