import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabase';
import { Student } from '../types';
import { LogOut, RefreshCw, AlertCircle, Volume2, School } from 'lucide-react';

interface TeacherViewProps {
  onLogout: () => void;
}

export const TeacherView: React.FC<TeacherViewProps> = ({ onLogout }) => {
  const [students, setStudents] = useState<Student[]>([]);
  const [activeTab, setActiveTab] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');

  const isActive = (student: Student) => {
    if (!student.last_called_at) return false;
    const diff = new Date().getTime() - new Date(student.last_called_at).getTime();
    return diff < 3 * 60 * 60 * 1000;
  };

  const fetchStudents = async () => {
    setLoading(true);
    setErrorMsg('');

    const { data, error } = await supabase
      .from('students')
      .select('*')
      .order('class_name', { ascending: true })
      .order('student_name', { ascending: true });

    if (error) {
      console.error('Error fetching students:', error);
      setErrorMsg(error.message);
    } else if (data) {
      setStudents(data as Student[]);
      if (!activeTab && data.length > 0) {
        setActiveTab((data[0] as Student).class_name);
      }
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchStudents();

    const channel = supabase
      .channel('public:students')
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'students' },
        (payload) => {
          const updatedStudent = payload.new as Student;
          setStudents((prev) =>
            prev.map((s) => (s.id === updatedStudent.id ? updatedStudent : s))
          );
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const classes = Array.from(new Set(students.map((s) => s.class_name))).sort();
  const filteredStudents = students.filter((s) => s.class_name === activeTab);

  return (
    <div className="flex flex-col h-screen bg-gray-50/50 relative overflow-hidden">
      {/* Subtle Background Elements */}
      <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-500/10 rounded-full blur-[100px] pointer-events-none" />
      <div className="absolute bottom-0 left-0 w-96 h-96 bg-pink-500/10 rounded-full blur-[100px] pointer-events-none" />

      {/* Dashboard Header */}
      <header className="glass-panel sticky top-0 z-30 px-6 py-4 shadow-sm border-b border-white/50">
        <div className="flex justify-between items-center max-w-7xl mx-auto">
          <div className="flex items-center gap-4">
            <img src="https://i.ibb.co/bgFrgXkW/meis.png" className="h-12 w-auto drop-shadow-md" alt="Logo" />
            <div className="hidden sm:block">
              <h1 className="text-xl font-bold text-gray-900 leading-tight">Teacher Dashboard</h1>
              <p className="text-xs text-gray-500 font-medium">Real-time Pickup Monitor</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
               onClick={fetchStudents}
               className="p-2.5 bg-white/50 hover:bg-white text-gray-600 hover:text-indigo-600 rounded-xl transition-all border border-transparent hover:border-indigo-100 shadow-sm"
               title="Refresh Data"
            >
              <RefreshCw className="w-5 h-5" />
            </button>
            <button
              onClick={onLogout}
              className="flex items-center gap-2 text-sm font-semibold text-white bg-gradient-to-r from-red-500 to-pink-600 hover:from-red-600 hover:to-pink-700 px-5 py-2.5 rounded-xl shadow-lg shadow-red-500/20 transition-all hover:scale-105"
            >
              <LogOut className="w-4 h-4" />
              <span className="hidden sm:inline">Logout</span>
            </button>
          </div>
        </div>

        {/* Horizontal Scrollable Tabs */}
        <div className="mt-6 flex gap-2 overflow-x-auto pb-2 no-scrollbar max-w-7xl mx-auto">
          {classes.map((cls) => (
            <button
              key={cls}
              onClick={() => setActiveTab(cls)}
              className={`px-5 py-2.5 rounded-xl text-sm font-bold whitespace-nowrap transition-all duration-300 ${
                activeTab === cls
                  ? 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg shadow-blue-500/30 scale-105'
                  : 'bg-white/70 text-gray-600 hover:bg-white hover:text-indigo-600 border border-transparent hover:border-indigo-100 backdrop-blur-sm'
              }`}
            >
              Class {cls}
            </button>
          ))}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto p-6 scroll-smooth">
        <div className="max-w-7xl mx-auto">
          {loading ? (
            <div className="flex flex-col justify-center items-center h-64 gap-4">
              <div className="relative">
                 <div className="w-12 h-12 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin"></div>
              </div>
              <p className="text-gray-500 font-medium">Loading class data...</p>
            </div>
          ) : errorMsg ? (
            <div className="flex flex-col justify-center items-center h-64 text-red-500 gap-3">
              <div className="p-3 bg-red-100 rounded-full">
                <AlertCircle className="w-8 h-8" />
              </div>
              <p className="font-medium text-lg">System Error</p>
              <p className="text-sm text-gray-600 bg-white px-4 py-2 rounded-lg border border-red-100">{errorMsg}</p>
            </div>
          ) : filteredStudents.length === 0 ? (
            <div className="flex flex-col justify-center items-center h-64 text-gray-400 gap-4">
              <div className="p-6 bg-white/50 rounded-full border border-dashed border-gray-300">
                <School className="w-12 h-12 opacity-50" />
              </div>
              <p className="text-lg font-medium">No students found in Class {activeTab}.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 pb-20">
              {filteredStudents.map((student) => {
                const active = isActive(student);
                return (
                  <div
                    key={student.id}
                    className={`relative p-6 rounded-3xl border transition-all duration-500 group ${
                      active
                        ? 'bg-gradient-to-br from-green-500 to-emerald-600 border-transparent text-white shadow-xl shadow-green-500/30 transform scale-[1.02] z-10'
                        : 'bg-white/80 border-white/50 text-gray-800 hover:bg-white hover:shadow-xl hover:shadow-indigo-900/5 hover:-translate-y-1 backdrop-blur-sm'
                    }`}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1 pr-2">
                        <h3 className={`text-xl font-bold leading-tight ${active ? 'text-white' : 'text-gray-900'}`}>
                          {student.student_name}
                        </h3>
                        {/* Removed Student ID display as requested */}
                      </div>
                      {active && (
                         <div className="p-2 bg-white/20 rounded-lg backdrop-blur-md animate-pulse">
                           <Volume2 className="w-5 h-5 text-white" />
                         </div>
                      )}
                    </div>

                    <div className="mt-6 flex items-center justify-between">
                      <div className={`px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${
                        active 
                          ? 'bg-white/20 text-white backdrop-blur-sm' 
                          : 'bg-gray-100 text-gray-500'
                      }`}>
                        {active ? 'Waiting Now' : 'In Class'}
                      </div>

                      {active && (
                        <span className="flex h-3 w-3">
                          <span className="animate-ping absolute inline-flex h-3 w-3 rounded-full bg-white opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-3 w-3 bg-white"></span>
                        </span>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

import React, { useState } from 'react';
import { supabase } from '../services/supabase';
import { Student } from '../types';
import { Phone, Search, Loader2, CheckCircle2, User, Sparkles, X, Users } from 'lucide-react';

export const ParentView: React.FC = () => {
  const [mobileInput, setMobileInput] = useState('');
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);
  const [calling, setCalling] = useState(false);
  const [error, setError] = useState('');
  const [showResultsModal, setShowResultsModal] = useState(false);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!mobileInput.trim()) return;

    setLoading(true);
    setError('');
    setStudents([]);
    setShowResultsModal(false);

    try {
      const { data, error } = await supabase.rpc('match_parent_mobile', {
        search_number: mobileInput.trim(),
      });

      if (error) throw error;

      if (data) {
        setStudents(data as Student[]);
        if (data.length === 0) {
          setError('No students found linked to this number.');
        } else {
          setShowResultsModal(true);
        }
      }
    } catch (err: any) {
      console.error('Error searching students:', err);
      setError(err.message || 'Failed to search. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleCallAll = async () => {
    if (students.length === 0) return;
    setCalling(true);

    try {
      const now = new Date().toISOString();
      const ids = students.map(s => s.id);

      // Batch update all students found
      const { error } = await supabase
        .from('students')
        .update({ last_called_at: now })
        .in('id', ids);

      if (error) throw error;

      // Optimistic update
      setStudents((prev) =>
        prev.map((s) => ({ ...s, last_called_at: now }))
      );
    } catch (err: any) {
      console.error('Error calling students:', err);
      alert(`Failed to update status: ${err.message}`);
    } finally {
      setCalling(false);
    }
  };

  const isCallRecent = (lastCalledAt: string | null) => {
    if (!lastCalledAt) return false;
    const diff = new Date().getTime() - new Date(lastCalledAt).getTime();
    return diff < 3 * 60 * 60 * 1000;
  };

  const allCalledRecently = students.length > 0 && students.every(s => isCallRecent(s.last_called_at));

  return (
    <div className="flex flex-col items-center">
      {/* Search Card */}
      <div className="glass-panel w-full max-w-lg rounded-3xl p-8 shadow-2xl shadow-indigo-900/10 mb-8 border border-white/60 relative overflow-hidden">
        {/* Decorative gradient inside card */}
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500"></div>

        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-gradient-to-br from-blue-500 to-indigo-600 text-white mb-5 shadow-lg shadow-blue-500/30 transform rotate-3">
            <Sparkles className="w-7 h-7" />
          </div>
          <h1 className="text-3xl font-bold text-gray-800 mb-2">School Pickup System</h1>
          <p className="text-gray-500 font-medium">Enter the registered father mobile number</p>
        </div>

        <form onSubmit={handleSearch} className="space-y-6">
          <div className="relative group">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
              <Phone className="h-6 w-6 text-gray-600 group-focus-within:text-indigo-600 transition-colors" />
            </div>
            <input
              type="number"
              className="block w-full pl-14 pr-4 py-4 bg-white/70 border border-gray-200 rounded-2xl text-lg placeholder-gray-400 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 focus:bg-white transition-all duration-300 outline-none backdrop-blur-sm shadow-sm [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
              placeholder=""
              value={mobileInput}
              onChange={(e) => setMobileInput(e.target.value)}
            />
          </div>
          <button
            type="submit"
            disabled={loading || !mobileInput}
            className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-bold text-lg py-4 px-6 rounded-2xl shadow-lg shadow-indigo-600/20 transform transition-all duration-300 hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Search className="w-6 h-6" />}
            Find Students
          </button>
        </form>

        {error && (
          <div className="mt-6 p-4 bg-red-50/80 backdrop-blur-sm text-red-600 rounded-xl text-center text-sm font-medium border border-red-100 animate-in fade-in slide-in-from-top-2">
            {error}
          </div>
        )}
      </div>

      {/* Results Modal */}
      {showResultsModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-md animate-in fade-in duration-200">
          <div className="bg-white/95 w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 slide-in-from-bottom-4 duration-300 border border-white/50">
